import { useState, useEffect } from 'react';

import clsx from 'clsx';
import { Link, useLocation } from 'react-router-dom';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { declOfNum } from '@helpers/formatHelper';
import PohBadge from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohIcon from '@ui-kit/Icon';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import PohTabs from '@ui-kit/Tabs';

import FilterPanel, { emptyHikingListFilters, IHikingListFilterCriteria } from './FilterPanel';
import OneHikingListItem from './OneHikingListItem';
import {
  getHikingListWithPagination,
  IHikingListWithPaginationCriteria,
} from '../../@services/hiking.service';
import { IHikingListItem } from '../../@types/hikingList.types';

const showMoreCount = 10;

interface IHikingListCategory {
  id: string;
  title: string;
  filterOptions: Record<string, string>;
  emptyMessage?: React.ReactNode;
}

const categories: IHikingListCategory[] = [
  {
    id: 'actual',
    title: 'Актуальные',
    filterOptions: { mode: 'actual' },
    emptyMessage: (
      <section className="text-center">
        <p>
          В данный момент нет актуальных походов.
          <br /> Но это легко исправить...
        </p>
        <Link to="/hiking/new">Организовать поход</Link>
      </section>
    ),
  },
  {
    id: 'completed',
    title: 'Завершенные',
    filterOptions: { mode: 'old', whose: 'my' },
  },
  {
    id: 'missed',
    title: 'Остальные',
    filterOptions: { mode: 'old', whose: 'all' },
  },
];

const getDataAndTotalCountAsync = async (
  id: string,
  params: IHikingListWithPaginationCriteria,
): Promise<[string, IHikingListItem[], number]> => {
  const { data: fetchedData, totalCount } = await getHikingListWithPagination(params);
  return [id, fetchedData, totalCount];
};

const defaultTabsState = categories.reduce(
  (acc, val) => ({
    ...acc,
    [val.id]: {
      isLoading: true,
      moreLoading: false,
      title: val.title,
      params: {
        ...val.filterOptions,
        limit: showMoreCount,
        offset: 0,
      },
    },
  }),
  {},
);

function HikingListsPage() {
  const location = useLocation();
  const filtersFromUrl = Object.fromEntries(new URLSearchParams(location.search)) || {};
  const [filters, setFilters] = useState<Partial<IHikingListFilterCriteria>>({
    ...emptyHikingListFilters,
    ...filtersFromUrl,
    region: filtersFromUrl.region ? +filtersFromUrl.region : null,
    type: filtersFromUrl.type ? +filtersFromUrl.type : null,
  });
  const [tabsState, setTabsState] = useState<any>(defaultTabsState);
  const [showFilterPanel, setShowFilterPanel] = useState(
    Object.entries(filtersFromUrl)?.length > 0,
  );

  useEffect(() => {
    const fetchAll = async () => {
      const tasks = categories.map(({ id }) =>
        getDataAndTotalCountAsync(id, {
          ...tabsState[id].params,
          ...Object.entries(filters).reduce<any>((acc, [k, v]) => {
            if (v) acc[k] = v;
            return acc;
          }, {}),
        }),
      );

      const dataArr = await Promise.all(tasks);

      const patch = dataArr.reduce(
        (acc, [id, data, totalCount]) => ({
          ...acc,
          [id]: {
            ...tabsState[id],
            data,
            totalCount,
            isLoading: false,
          },
        }),
        {},
      );

      setTabsState(patch);
    };

    fetchAll();
  }, [filters]);

  const showMore = async (id: string) => {
    setTabsState({
      ...tabsState,
      [id]: {
        ...tabsState[id],
        moreLoading: true,
      },
    });

    const [, data, totalCount] = await getDataAndTotalCountAsync(id, {
      ...tabsState[id].params,
      offset: tabsState[id].data.length,
    });

    setTabsState({
      ...tabsState,
      [id]: {
        ...tabsState[id],
        data: [...tabsState[id].data, ...data],
        totalCount,
        moreLoading: false,
      },
    });
  };

  const getTabs = () =>
    categories.map(({ id, title, emptyMessage }) => {
      const tabData = tabsState[id];

      let badgeContent = null;

      if (tabData?.totalCount) {
        badgeContent = tabData.totalCount.toString();
      }

      let showMoreBtn = false;
      let diff = 0;

      if (tabData?.data?.length) {
        diff = tabData.totalCount - tabData.data.length;
        showMoreBtn = diff > 0 || tabData.moreLoading;
      }
      const moreAvailable = diff > showMoreCount ? showMoreCount : diff;

      return {
        key: id,
        title: (
          <>
            {title} {badgeContent && <PohBadge>{badgeContent}</PohBadge>}
          </>
        ),
        content: tabData.isLoading ? (
          <PageLoader />
        ) : (
          <>
            {!tabData?.data?.length && <Empty>{emptyMessage || 'Не найдено походов'}</Empty>}
            {!!tabData?.data?.length && (
              <>
                <PohList
                  className="mt-2"
                  data={tabData.data.map((x: any) => ({
                    key: x.id,
                    as: Link,
                    to: `/hiking/${x.id}`,
                    action: true,
                    style: { textDecoration: 'none' },
                    content: <OneHikingListItem item={x} />,
                  }))}
                />
                <PohRow className="mt-3">
                  <PohCol sm={4} className="text-muted align-items-center">
                    Показано: {tabData.data.length} из {tabData.totalCount}{' '}
                    {declOfNum(tabData.totalCount, ['похода', 'походов', 'походов'])}
                  </PohCol>
                  <PohCol sm={4} className="text-center">
                    {!!showMoreBtn && (
                      <PohButton
                        variant={ButtonVariant.Light}
                        onClick={() => showMore(id)}
                        disabled={tabData.moreLoading}
                      >
                        {tabData.moreLoading ? (
                          <PohLoader />
                        ) : (
                          `Показать ещё ${moreAvailable} ${declOfNum(moreAvailable, ['поход', 'похода', 'походов'])}`
                        )}
                      </PohButton>
                    )}
                  </PohCol>
                  <PohCol sm={4} />
                </PohRow>
              </>
            )}
          </>
        ),
      };
    });

  return (
    <PohContainer>
      <PageHeader title="Походы">
        <PohButton
          as={Link as any}
          // eslint-disable-next-line @typescript-eslint/ban-ts-comment
          // @ts-ignore
          to="/hiking/new"
          style={{ width: '220px' }}
          variant={ButtonVariant.Success}
          size={ButtonSize.Small}
          onClick={() => {}}
        >
          Создать поход
        </PohButton>
        <PohButton
          onClick={() => setShowFilterPanel((c) => !c)}
          className={clsx(showFilterPanel && 'active', 'ms-1')}
          variant={ButtonVariant.Light}
        >
          <PohIcon name={IconsEnum.filterOutline} />
        </PohButton>
      </PageHeader>

      <PohRow>
        <PohCol md={showFilterPanel ? 8 : 12}>
          <PohTabs useHash tabs={getTabs()} />
        </PohCol>
        {showFilterPanel && (
          <PohCol md={4}>
            <h5>Фильтры</h5>
            <FilterPanel
              onChange={(patch) => {
                setFilters(patch);
                history.pushState(
                  '',
                  '',
                  location.pathname + '?' + new URLSearchParams(patch as any) + location.hash,
                );
              }}
              value={filters as any}
            />
          </PohCol>
        )}
      </PohRow>
    </PohContainer>
  );
}

export default HikingListsPage;
