import React, { FormEvent } from 'react';

import { getGeoRegionsAsync, IGeoRegion } from '@apps/Routes/@services/geo.services';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import PohInput, { InputSizes, InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohLoader from '@ui-kit/Loader';
import PohSelect from '@ui-kit/Select';

import { getHikingTypesAsync } from '../../../@services/hiking.service';
import { IHikingType } from '../../../@types/hiking.types';

export interface IHikingListFilterCriteria {
  d1: string;
  d2: string;
  type: number | null;
  region: number | null;
}

export const emptyHikingListFilters: IHikingListFilterCriteria = {
  d1: '',
  d2: '',
  type: null,
  region: null,
};

interface IHikingFilterPanelProps {
  onChange: (d: Partial<IHikingListFilterCriteria>) => void;
  value?: IHikingListFilterCriteria;
}

function FilterPanel({ onChange, value = emptyHikingListFilters }: IHikingFilterPanelProps) {
  const [data, setData] = React.useState<{ types: IHikingType[]; regions: IGeoRegion[] } | null>(
    null,
  );
  const [filters, setFilters] = React.useState<IHikingListFilterCriteria>(value);

  React.useEffect(() => {
    const fetch = async () => {
      const [types, regions] = await Promise.all([getHikingTypesAsync(), getGeoRegionsAsync()]);
      setData({ types, regions });
    };

    fetch();
  }, []);

  const updateFilterValue = (patch: Partial<IHikingListFilterCriteria>) =>
    setFilters({ ...filters, ...patch });

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    onChange(
      Object.entries(filters).reduce<any>((acc, [k, v]) => {
        if (v) acc[k] = v;
        return acc;
      }, {}),
    );
  };

  const handleReset = () => {
    setFilters(emptyHikingListFilters);
    onChange({});
  };

  return (
    <PohRow className="mb-2">
      <PohCol xs={12}>
        {data == null && <PohLoader>cxc</PohLoader>}
        {data && (
          <PohCard>
            <form onSubmit={handleSubmit}>
              <PohRow className="mb-2">
                <PohCol sm={6}>
                  <PohInput
                    label="Дата (от)"
                    type={InputTypes.date}
                    size={InputSizes.Small}
                    onChange={(val) => updateFilterValue({ d1: val })}
                    value={filters.d1}
                  />
                </PohCol>
                <PohCol sm={6}>
                  <PohInput
                    label="Дата (до)"
                    type={InputTypes.date}
                    size={InputSizes.Small}
                    value={filters.d2}
                    onChange={(val) => updateFilterValue({ d2: val })}
                  />
                </PohCol>
              </PohRow>
              <PohRow className="mb-2">
                <PohCol sm={12}>
                  <PohSelect
                    label="Тип похода"
                    size={InputSizes.Small}
                    placeholder="Все типы"
                    value={filters.type}
                    options={data.types.map(({ id, name }) => ({ value: id, label: name }))}
                    onChange={(val) => updateFilterValue({ type: val })}
                    allowEmpty
                  />
                </PohCol>
              </PohRow>
              <PohRow className="mb-2">
                <PohCol sm={12}>
                  <PohSelect
                    label="Регион"
                    size={InputSizes.Small}
                    placeholder="Все Регионы"
                    options={data.regions.map(({ id, name }) => ({ value: id, label: name }))}
                    value={filters.region}
                    onChange={(val) => updateFilterValue({ region: val })}
                    allowEmpty
                  />
                </PohCol>
              </PohRow>
              <hr />
              <PohRow className="mb-2">
                <PohCol sm={6}>
                  <PohButton block variant={ButtonVariant.Light} onClick={handleReset}>
                    Сбросить
                  </PohButton>
                </PohCol>
                <PohCol sm={6}>
                  <PohButton block variant={ButtonVariant.Primary} type="submit">
                    Применить
                  </PohButton>
                </PohCol>
              </PohRow>
            </form>
          </PohCard>
        )}
      </PohCol>
    </PohRow>
  );
}

export default FilterPanel;
